import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"[Alcune proprietà importanti]","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/g_geometria-dello-spazio/gh/ghc.md","filePath":"lezioni/g_geometria-dello-spazio/gh/ghc.md"}`),a={name:`lezioni/g_geometria-dello-spazio/gh/ghc.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 class="text-red-darken-1" id="alcune-proprieta-importanti" tabindex="-1">[Alcune proprietà importanti] <a class="header-anchor" href="#alcune-proprieta-importanti" aria-label="Permalink to “[Alcune proprietà importanti]”">​</a></h1><p>Abbiamo detto che il triedro è pressappoco come un angolo, meglio sarebbe dire che è come un triangolo (inteso come insieme di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>3</mn></mrow><annotation encoding="application/x-tex">3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span> angoli) nello spazio, e quindi ha delle interessanti proprietà comuni con la figura (triangolo classico) studiata in geometria del piano.</p><p>Naturalmente questo vale anche per gli angoloidi pensati come insiemi di più angoli.</p><p>Esplicitiamo alcune proprietà, ricordando che un triedro è un angoloide con <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>3</mn></mrow><annotation encoding="application/x-tex">3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span> facce.</p><ul><li>In un triedro ogni faccia è minore della somma delle altre due</li><li>In un triedro ogni faccia è maggiore della differenza delle altre due</li><li>In un angoloide ogni faccia è minore della somma di tutte le altre</li><li>In un angoloide la somma delle facce è minore di un angolo giro</li></ul>`,5)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};